draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // dog body
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();

  // head
  ctx.beginPath();
  ctx.arc(W/2, H/2 - 30, 15, 0, 2 * Math.PI);
  ctx.stroke();

  // ears
  ctx.beginPath();
  ctx.moveTo(W/2 - 10, H/2 - 40);
  ctx.lineTo(W/2 - 20, H/2 - 60 + 10 * Math.sin(t));
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2 + 10, H/2 - 40);
  ctx.lineTo(W/2 + 20, H/2 - 60 + 10 * Math.sin(t + Math.PI));
  ctx.stroke();

  // legs
  ctx.beginPath();
  ctx.moveTo(W/2 - 15, H/2 + 10);
  ctx.lineTo(W/2 - 25, H/2 + 30 + 10 * Math.sin(t));
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2 + 15, H/2 + 10);
  ctx.lineTo(W/2 + 25, H/2 + 30 + 10 * Math.sin(t + Math.PI));
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2 - 15, H/2 + 10);
  ctx.lineTo(W/2 - 15, H/2 + 30 + 10 * Math.sin(t + Math.PI/2));
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2 + 15, H/2 + 10);
  ctx.lineTo(W/2 + 15, H/2 + 30 + 10 * Math.sin(t - Math.PI/2));
  ctx.stroke();

  // tail
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2 + 20 * Math.sin(t), H/2 + 40);
  ctx.stroke();

  ctx.restore();
}
